'use strict';

// MODULES //

var isPositiveInteger = require( '@stdlib/assert/is-positive-integer' ).isPrimitive;
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var format = require( '@stdlib/string/format' );


// MAIN //

/**
* Returns an accumulator function which incrementally computes a moving unbiased sample variance, ignoring NaN values.
*
* @param {PositiveInteger} W - window size
* @param {number} [mean] - mean value
* @throws {TypeError} first argument must be a positive integer
* @throws {TypeError} second argument must be a number
* @returns {Function} accumulator function
*
* @example
* var accumulator = incrnanmvariance( 3 );
*
* var s2 = accumulator();
* // returns null
*
* s2 = accumulator( 2.0 );
* // returns 0.0
*
* s2 = accumulator( NaN );
* // returns 0.0
*
* s2 = accumulator( -5.0 );
* // returns 24.5
*
* s2 = accumulator( 3.0 );
* // returns 19.0
*
* s2 = accumulator( NaN );
* // returns 19.0
*
* s2 = accumulator();
* // returns 19.0
*
* @example
* var accumulator = incrnanmvariance( 3, -2.0 );
*/
function incrnanmvariance( W, mean ) {
	var delta;
	var buf;
	var tmp;
	var M2;
	var mu;
	var d1;
	var d2;
	var N;
	var n;
	var i;

	if ( !isPositiveInteger( W ) ) {
		throw new TypeError( format( 'invalid argument. Must provide a positive integer. Value: `%s`.', W ) );
	}

	buf = new Array( W );
	n = W - 1;
	M2 = 0.0;
	i = -1;
	N = 0;

	if ( arguments.length > 1 ) {
		if ( !isNumber( mean ) ) {
			throw new TypeError( format( 'invalid argument. Must provide a number. Value: `%s`.', mean ) );
		}
		mu = mean;
		return accumulator2;
	}

	mu = 0.0;
	return accumulator1;

	/**
	* If provided a value, the accumulator function returns an updated unbiased sample variance, ignoring NaN values. If not provided a value, the accumulator function returns the current unbiased sample variance.
	*
	* @private
	* @param {number} [x] - input value
	* @returns {(number|null)} unbiased sample variance or null
	*/
	function accumulator1( x ) {
		var k;
		var v;

		if ( arguments.length === 0 ) {
			if ( N === 0 ) {
				return null;
			}
			if ( N === 1 ) {
				return 0.0;
			}
			if ( N < W ) {
				return M2 / (N-1);
			}
			return M2 / n;
		}

		// If incoming value is NaN, ignore it:
		if ( isnan( x ) ) {
			return ( N === 0 ) ? null : ( N === 1 ) ? 0.0 : ( N < W ) ? M2 / (N-1) : M2 / n;
		}

		// Update the index for managing the circular buffer:
		i = (i+1) % W;

		// Case: initial window...
		if ( N < W ) {
			buf[ i ] = x; // update buffer
			N += 1;
			delta = x - mu;
			mu += delta / N;
			M2 += delta * (x - mu);
			if ( N === 1 ) {
				return 0.0;
			}
			return M2 / (N-1);
		}

		// Case: N = W = 1
		else if ( N === 1 ) {
			M2 = 0.0;
			return M2;
		}

		// Case: outgoing value is NaN, which we need to simply replace without affecting the variance
		else if ( isnan( buf[ i ] ) ) {
			buf[ i ] = x;
			// When replacing NaN with a value, we need to update M2 with the squared difference from mean
			M2 += (x - mu) * (x - mu);
			return M2 / n;
		}

		// Case: standard update when neither incoming nor outgoing values are NaN
		else {
			tmp = buf[ i ];
			delta = x - tmp;
			d1 = tmp - mu;
			mu += delta / N;
			d2 = x - mu;
			M2 += delta * (d1 + d2);
		}

		buf[ i ] = x;
		return M2 / n;
	}

	/**
	* If provided a value, the accumulator function returns an updated unbiased sample variance, ignoring NaN values. If not provided a value, the accumulator function returns the current unbiased sample variance.
	*
	* @private
	* @param {number} [x] - input value
	* @returns {(number|null)} unbiased sample variance or null
	*/
	function accumulator2( x ) {
		var k;

		if ( arguments.length === 0 ) {
			if ( N === 0 ) {
				return null;
			}
			if ( N < W ) {
				return M2 / N;
			}
			return M2 / W;
		}

		// If incoming value is NaN, ignore it:
		if ( isnan( x ) ) {
			return ( N === 0 ) ? null : ( N < W ) ? M2 / N : M2 / W;
		}

		// Update the index for managing the circular buffer:
		i = (i+1) % W;

		// Case: initial window...
		if ( N < W ) {
			buf[ i ] = x; // update buffer
			N += 1;
			delta = x - mu;
			M2 += delta * delta;
			return M2 / N;
		}

		// Case: outgoing value is NaN, which we need to simply replace without affecting the variance
		else if ( isnan( buf[ i ] ) ) {
			buf[ i ] = x;
			// Add the squared difference between the new value and mean
			M2 += (x - mu) * (x - mu);
			return M2 / W;
		}

		// Case: standard update when neither incoming nor outgoing values are NaN
		else {
			tmp = buf[ i ];
			// Remove the contribution of the outgoing value
			M2 -= (tmp - mu) * (tmp - mu);
			// Add the contribution of the incoming value
			M2 += (x - mu) * (x - mu);
		}

		buf[ i ] = x;
		return M2 / W;
	}
}


// EXPORTS //

module.exports = incrnanmvariance;
